cardCss:
.dino-card {
    background: var(--card-bg, #ffffff);
    border-radius: 16px;
    padding: 14px 18px;
    box-shadow: 0 1px 3px rgba(87, 130, 69, 0.08);
    border: 1px solid var(--line, #e6e6e6);
    border-left: 4px solid #4d7c0f;
    margin-bottom: 16px;
    transition: transform 0.25s, box-shadow 0.25s, border-color 0.25s;
}
.dino-card:hover { transform: translateY(-3px); box-shadow: 0 10px 26px rgba(87, 130, 69, 0.12); border-color: #a3e635; }
.dino-card:active { transform: scale(0.99); }
.dino-header { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; }
.dino-index { color: var(--ink-3, #64748b); font-size: calc(12px * var(--card-font-scale, 1)); font-weight: 600; }
.dino-name { font-size: calc(26px * var(--card-font-scale, 1)); font-weight: 800; color: #3f6212; letter-spacing: 1px; }
.dino-body { display: flex; flex-direction: column; gap: 8px; margin-bottom: 10px; }
.dino-section { padding: 6px 10px; border-radius: 8px; background: var(--slate-soft, #f1f5f9); }
.dino-label { font-size: 11px; font-weight: 700; color: var(--ink-3, #64748b); text-transform: uppercase; letter-spacing: 1px; margin-bottom: 2px; }
.dino-latin { font-size: calc(14px * var(--card-font-scale, 1)); color: var(--ink-2, #475569); font-style: italic; }
.dino-desc { font-size: calc(14px * var(--card-font-scale, 1)); color: var(--ink, #1d1d1d); line-height: 1.6; }
.dino-actions { display: flex; gap: 8px; }
.dino-actions .action-btn {
    width: 40px; height: 40px; border: none; background: var(--action-btn-bg, #f1f5f9);
    border-radius: 90px; cursor: pointer; display: flex; align-items: center; justify-content: center;
    color: var(--ink-3, #64748b); transition: all 0.2s;
}
.dino-actions .action-btn i { width: 20px; height: 20px; }
.dino-actions .action-btn:hover { transform: translateY(-2px); }
.dino-actions .act-play:hover { background: #4d7c0f; color: #fff; }
.dino-actions .act-mark.is-active { background: var(--unknown, #f43f5e); color: #fff; }
.dino-actions .act-fav.is-active { background: var(--amber, #d97706); color: #fff; }

cardJs:
(function () {
    'use strict';
    window.cardTemplate = {
        name: 'Dinosaur 3D Card',
        fields: [
            { key: 'name', label: '名称', hideable: false },
            { key: 'model', label: '3D 模型', type: 'model' },
            { key: 'latin', label: '学名' },
            { key: 'desc', label: '介绍' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var mode = api.getViewMode ? api.getViewMode() : 'list';
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(key) { return hidden.has && hidden.has(key); }
            function wrap(key, content) { return isHidden(key) ? '' : content; }
            var markActive = data.is_unknown === 1 ? 'is-active' : '';
            var favActive = data.is_favorite === 1 ? 'is-active' : '';
            /* In resource mode the 3D model is shown in the canvas above,
               so the info section only renders text fields (no model). */
            return '<div class="dino-card" data-card-id="' + data.id + '">' +
                '<div class="dino-header">' +
                '<span class="dino-index">' + String(data.current_order).padStart(2, '0') + '</span>' +
                wrap('name', '<span class="dino-name">' + (d.name || '') + '</span>') +
                '</div>' +
                '<div class="dino-body">' +
                '<div class="dino-section"><div class="dino-label">' + (mode === 'resource' ? '' : '') + '</div><div class="dino-latin">' + (d.latin || '') + '</div></div>' +
                '<div class="dino-section"><div class="dino-label">介绍</div><div class="dino-desc">' + (d.desc || '') + '</div></div>' +
                '</div>' +
                '<div class="dino-actions">' +
                '<button class="action-btn act-play" data-action="play" data-tooltip="Play"><i class="fa-solid fa-volume-high"></i></button>' +
                '<button class="action-btn act-mark ' + markActive + '" data-action="mark" data-tooltip="Mark"><i class="fa-solid fa-star"></i></button>' +
                '<button class="action-btn act-fav ' + favActive + '" data-action="favorite" data-tooltip="Favorite"><i class="fa-solid fa-bookmark"></i></button>' +
                '</div>' +
                '</div>';
        },
        init: function (cardElement, cardData, api) {
            var playBtn = cardElement.querySelector('[data-action="play"]');
            if (playBtn) playBtn.addEventListener('click', function () {
                var d = cardData.data || {};
                if (d.name) api.playAudio(d.name);
                api.track('audio_play');
            });
            var markBtn = cardElement.querySelector('[data-action="mark"]');
            if (markBtn) markBtn.addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var favBtn = cardElement.querySelector('[data-action="favorite"]');
            if (favBtn) favBtn.addEventListener('click', function () {
                api.toggleFavorite().then(function () { api.rerender(); });
                api.track('favorite_toggle');
            });
        },
        update: function (cardElement, cardData, api) {
            var p = cardElement.parentElement;
            if (p) { cardElement.outerHTML = this.render('', cardData, api); }
        }
    };
})();
